import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.DncwoWA8.js";const n="/projects/ai-skills/diagrams/document-a-project.svg",m=JSON.parse('{"title":"Document a project","description":"","frontmatter":{"title":"Document a project"},"headers":[],"relativePath":"workflows/document-a-project.md","filePath":"workflows/document-a-project.md"}'),r={name:"workflows/document-a-project.md"};function i(p,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="document-a-project" tabindex="-1">Document a project <a class="header-anchor" href="#document-a-project" aria-label="Permalink to &quot;Document a project&quot;">​</a></h1><p>Create or improve a documentation website that helps a developer complete useful project tasks without the author&#39;s help.</p><p>Start with a project, its intended readers, and permission for a bounded documentation effort. Finish with checked guides, examples, reference material, and navigation. This workflow covers both an existing site and an approved new site.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p><img src="'+n+`" alt="Reader-oriented documentation with existing-site and approved new-site routes."></p><p><a href="/projects/ai-skills/diagrams/document-a-project.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/document-a-project.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/document-a-project.json">Editable source</a></p><p>The diagram shows suggested handoffs, not automatic execution or new instruction dependencies. Select a node in the interactive diagram for its source references.</p><details><summary>Read the flow as text</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Inspect project and reader tasks</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Agree coverage and site scope</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Organize the reader&#39;s route</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Write guides and reference</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Walk through → build → link checks</span></span>
<span class="line"><span>    └─ gaps → revise and recheck</span></span></code></pre></div></details><p>Writing style applies throughout the work. It is not a separate sequence of skill invocations after every paragraph.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Read the project instructions, existing documentation, supported interfaces, configuration, tests, and working examples. Confirm the reader, supported platforms, intended coverage, and <a href="/projects/ai-skills/workflows/supporting-tools.html#before-you-start">execution safeguards</a>.</p><p>Use <a href="/projects/ai-skills/skills/document-project.html"><code>document-project</code></a> to organize the work. Apply <a href="/projects/ai-skills/skills/asd-ste100-technical.html"><code>asd-ste100-technical</code></a> for clear technical instructions and <a href="/projects/ai-skills/skills/unslop.html"><code>unslop</code></a> to remove filler while preserving meaning.</p><p>Improving documentation does not authorize a platform migration, dependency installation, unfamiliar-code execution, or publication.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-establish-what-the-reader-needs-to-do" tabindex="-1">1. Establish what the reader needs to do <a class="header-anchor" href="#_1-establish-what-the-reader-needs-to-do" aria-label="Permalink to &quot;1. Establish what the reader needs to do&quot;">​</a></h3><p>Choose real tasks such as first installation, configuration, exporting a report, or diagnosing a known failure. Identify each task&#39;s starting state and first observable result.</p><p>Inspect project evidence before deciding what to document. Separate supported behavior, observed defects, and intended future behavior. Resolve contradictions or disclose the missing evidence.</p><p>Do not use the source directory tree as the reading order. Explain project-specific terms, commands, permissions, and results while assuming standard development skills.</p><h3 id="_2-choose-the-existing-site-or-new-site-branch" tabindex="-1">2. Choose the existing-site or new-site branch <a class="header-anchor" href="#_2-choose-the-existing-site-or-new-site-branch" aria-label="Permalink to &quot;2. Choose the existing-site or new-site branch&quot;">​</a></h3><p>For an existing site, keep its approved platform and build process. Read affected pages, preserve correct content, and agree how moved pages and links will be handled.</p><p>If no site exists, propose the minimum useful baseline and obtain approval before creating it or installing tools. The <code>document-project</code> skill defaults to VitePress for an approved new site. An existing MkDocs site stays on MkDocs unless a migration is separately approved.</p><p>A documentation request is not permission for broad legacy cleanup. Keep unrelated reorganization out of a bounded guide update.</p><h3 id="_3-build-a-reader-oriented-structure" tabindex="-1">3. Build a reader-oriented structure <a class="header-anchor" href="#_3-build-a-reader-oriented-structure" aria-label="Permalink to &quot;3. Build a reader-oriented structure&quot;">​</a></h3><p>Give each page a clear purpose. A tutorial teaches one coherent example, a how-to completes a task, reference supports lookup, and explanation describes why the system works that way.</p><p>Lead the first-use route toward a working result. Link deeper architecture, maintenance, and release information when needed rather than putting it before every user&#39;s first task.</p><p>Choose one recommended route and introduce alternatives only where the reader must decide.</p><h3 id="_4-write-a-procedure-the-reader-can-follow" tabindex="-1">4. Write a procedure the reader can follow <a class="header-anchor" href="#_4-write-a-procedure-the-reader-can-follow" aria-label="Permalink to &quot;4. Write a procedure the reader can follow&quot;">​</a></h3><p>State prerequisites before actions. Supply exact supported commands or UI labels, starting files or inputs, relevant versions, working locations, expected results, and recovery for likely failures.</p><p>Use one small, coherent example. Mark proposed or illustrative output so it cannot be mistaken for an executed result. Do not guess project commands or require credentials merely to inspect the project.</p><p>Use a <a href="/projects/ai-skills/workflows/supporting-tools.html#diagrams-and-writing-aids">diagram</a> when it answers a relationship question. A screenshot or diagram does not replace the written procedure.</p><h3 id="_5-verify-both-the-site-and-the-instructions" tabindex="-1">5. Verify both the site and the instructions <a class="header-anchor" href="#_5-verify-both-the-site-and-the-instructions" aria-label="Permalink to &quot;5. Verify both the site and the instructions&quot;">​</a></h3><p>Walk the procedure from its stated starting point without relying on unwritten project knowledge. Check prerequisites, terms, placeholders, actions, outputs, failure recovery, and the next useful page.</p><p>Run the project&#39;s approved site build and available link checks. Check navigation, assets, downloads, moved links, and the configured URL base. A passing build does not prove that an example works.</p><p>Execute examples only with the required authority and safe input. Report executed examples, agent walkthroughs, and actual user testing separately. If a required check cannot run, report the blocker and obtain the owner&#39;s decision before treating the work as complete.</p><h2 id="example-document-report-export" tabindex="-1">Example: document report export <a class="header-anchor" href="#example-document-report-export" aria-label="Permalink to &quot;Example: document report export&quot;">​</a></h2><p>This example continues the illustrative reporting project. The paths below are proposed pages, not files supplied by this collection.</p><p>Suppose export already exists but users cannot discover how filters affect it. A bounded request could be:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Document the existing CSV export in the current documentation website.</span></span>
<span class="line"><span>Inspect the implemented filters, columns, limits, permissions, encoding,</span></span>
<span class="line"><span>and failure behavior. Write a task guide with one safe example and link</span></span>
<span class="line"><span>format details from reference. Preserve the current site platform and URLs.</span></span>
<span class="line"><span>Run its approved build and link checks. Do not deploy.</span></span></code></pre></div><p>A useful result might include:</p><table tabindex="0"><thead><tr><th>Proposed page</th><th>Reader result</th></tr></thead><tbody><tr><td><code>guide/export-reports.md</code></td><td>Export a filtered report and recognize the resulting file</td></tr><tr><td><code>reference/csv-format.md</code></td><td>Look up supported columns, quoting, encoding, and limits</td></tr><tr><td>The existing navigation</td><td>Find the guide from the reporting section</td></tr></tbody></table><p>Use the target site&#39;s actual paths and supported commands. If export behavior conflicts with a requirement, report that conflict instead of documenting an imagined correction.</p><h2 id="keep-documentation-with-behavior-changes" tabindex="-1">Keep documentation with behavior changes <a class="header-anchor" href="#keep-documentation-with-behavior-changes" aria-label="Permalink to &quot;Keep documentation with behavior changes&quot;">​</a></h2><p>This workflow can be a standalone project. Its affected-guide update also belongs inside implementation, debugging, and debloating when they change a reader task, public behavior, configuration, or interface.</p><p>For an internal-only change, explain concretely why no reader documentation needs to change. Do not add cosmetic edits merely to show documentation activity.</p><h2 id="hand-off-the-website" tabindex="-1">Hand off the website <a class="header-anchor" href="#hand-off-the-website" aria-label="Permalink to &quot;Hand off the website&quot;">​</a></h2><p>Report changed paths, covered reader tasks, navigation and link checks, build results, executed examples, walkthrough findings, and unresolved gaps. Stop before deployment unless it is separately authorized.</p><p>For work on this collection&#39;s own website, use <a href="/projects/ai-skills/maintenance/">site maintenance</a> for its actual setup and build commands. For a narrower maintenance procedure, see <a href="/projects/ai-skills/workflows/maintain-task-based-docs.html">Keep a developer task usable</a>.</p>`,47)])])}const f=t(r,[["render",i]]);export{m as __pageData,f as default};
